// The vendors' cloud architecture icon sets (#4) as built-in, read-only packs. Each set's drawings
// are a JSON file generated by scripts/cloud-icons.mjs from the vendor's official package, already
// reduced by `sanitizeSvg` (and drawn through `cleanIconNodes` again, like any icon). LAZY: each set
// is its own chunk, imported only when the library shows it, so none of it is in the board bundle.
import { CLOUD_ICON_SETS, cloudPackId, type CloudIconSetId, type IconNode, type ShapePack, type ShapePackIcon } from '@freero/shared';
import manifest from './cloud/manifest.json';

/** One icon as the generator writes it: name, the vendor's category, viewBox, drawing, extra search words. */
export type CloudIconRow = [name: string, group: string, viewBox: string, nodes: IconNode[], keywords?: string];
export interface CloudSetFile {
  id: string;
  icons: CloudIconRow[];
}

/** A built-in pack: a shape pack nobody uploaded, which nobody renames or removes. */
export interface CloudPack extends Omit<ShapePack, 'icons'> {
  cloud: CloudIconSetId;
  /** `words`: more to search by than the name (the vendor's category, Kubernetes' short names). */
  icons: Array<ShapePackIcon & { words: string }>;
}

export interface CloudSetInfo {
  id: CloudIconSetId;
  pack: string;
  name: string;
  /** Icons in the set (from the manifest, so the source picker can say before the set loads). */
  count: number;
  /** Where the vendor states its terms (shown with the set's notice). */
  terms: string;
}

export const CLOUD_SETS: CloudSetInfo[] = CLOUD_ICON_SETS.map(({ id, name }) => {
  const m = manifest.sets.find((s) => s.id === id);
  return { id, pack: cloudPackId(id), name, count: m?.icons ?? 0, terms: m?.terms ?? '' };
}).filter((s) => s.count > 0);

/**
 * One import() per set: one chunk per set, its JSON as a string (`?raw`: parsed once on arrival, and
 * the type checker never reads megabytes of drawings). Never import these files statically: the
 * board bundle would carry them (icons.test.ts checks).
 */
const FILES: Record<CloudIconSetId, () => Promise<{ default: string }>> = {
  aws: () => import('./cloud/aws.json?raw'),
  azure: () => import('./cloud/azure.json?raw'),
  kubernetes: () => import('./cloud/kubernetes.json?raw'),
};

/** A set's file as a pack; its icons search by name, the vendor's category and the extra words. */
export function packOf(id: CloudIconSetId, file: CloudSetFile): CloudPack {
  const name = CLOUD_ICON_SETS.find((s) => s.id === id)?.name ?? id;
  return {
    id: cloudPackId(id),
    cloud: id,
    name,
    createdBy: null,
    createdAt: 0,
    icons: file.icons.map(([iconName, group, viewBox, nodes, keywords], i) => ({
      id: `${cloudPackId(id)}:${i}`,
      name: iconName,
      nodes,
      viewBox,
      // Never recoloured: the vendors' terms ask for the icons as they are.
      art: 'color',
      words: `${group}${keywords ? ` ${keywords}` : ''}`,
    })),
  };
}

const loaded = new Map<CloudIconSetId, Promise<CloudPack>>();
/** The set, fetched once per page (a failed fetch is tried again next time). */
export function loadCloudPack(id: CloudIconSetId): Promise<CloudPack> {
  let p = loaded.get(id);
  if (!p) {
    p = FILES[id]().then(
      (m) => packOf(id, JSON.parse(m.default) as CloudSetFile),
      (e) => {
        loaded.delete(id);
        throw e;
      },
    );
    loaded.set(id, p);
  }
  return p;
}
